import React, { useState } from 'react';
import ChordDiagram from './ChordDiagram';

function ChordDetail({ chord }) {
  const [selectedVariationIndex, setSelectedVariationIndex] = useState(0);

  // Get variations array, default to empty if not present
  const variations = chord.variations || [];
  const hasVariations = variations.length > 0;

  // Determine which fingering to display: primary if no variations or index 0, else variation
  const displayFret = hasVariations && selectedVariationIndex > 0 
    ? variations[selectedVariationIndex - 1].frets 
    : chord.frets;
  const displayFingers = hasVariations && selectedVariationIndex > 0 
    ? variations[selectedVariationIndex - 1].fingers 
    : chord.fingers;

  // Label for the variation
  const variationLabel = hasVariations && selectedVariationIndex > 0 
    ? variations[selectedVariationIndex - 1].label || `Variation ${selectedVariationIndex}` 
    : 'Primary';

  const variationOptions = [
    { label: 'Primary', index: 0 },
    ...variations.map((v, i) => ({ label: v.label || `Variation ${i + 1}`, index: i + 1 }))
  ];

  return (
    <div className="chord-detail">
      <div className="chord-detail-header">
        <h3>{chord.name}</h3>
        {hasVariations && (
          <div className="variation-selector">
            <label htmlFor="variation-select">Variation: </label>
            <select 
              id="variation-select"
              value={selectedVariationIndex} 
              onChange={(e) => setSelectedVariationIndex(parseInt(e.target.value))}
              aria-label={`Select variation for ${chord.name} chord`}
            >
              {variationOptions.map(opt => (
                <option key={opt.index} value={opt.index}>
                  {opt.label}
                </option>
              ))}
            </select>
          </div>
        )}
      </div>
      <ChordDiagram 
        frets={displayFret} 
        fingers={displayFingers} 
        size={150} 
        className="chord-detail-diagram"
      />
      <div className="chord-detail-fingers">
        {displayFingers.filter(f => f > 0).length > 0
          ? `${displayFingers.filter(f => f > 0).length} finger${displayFingers.filter(f => f > 0).length > 1 ? 's' : ''}`
          : 'Open chord'}
      </div>
    </div>
  );
}

export default ChordDetail;
